function pickAt(e){const r=C.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;for(let f of hitFaces.slice().reverse()){let inside=false;for(let i=0,j=f.q.length-1;i<f.q.length;j=i++){const a=f.q[i],b=f.q[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])inside=!inside}if(inside){setPicked(f.idx);return}}}

