const cats=document.querySelector('#lab-categories');function showCat(cat){category=cat;cats.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.cat===cat)));modules.replaceChildren();let first=-1;models.forEach((m,i)=>{if(cat&&m.cat[1]!==cat)return;if(query&&!JSON.stringify([m.n,m.cat,m.d,m.a,m.p,knowledge[i]]).toLowerCase().includes(query))return;if(first<0)first=i;let b=document.createElement('button');b.dataset.model=i;b.textContent=t(m.n);b.onclick=()=>select(i);modules.append(b)});document.querySelector('#lab-count').textContent=(z?'当前模型：':'Models: ')+modules.querySelectorAll('button').length+' / '+models.length;if(first<0){modules.textContent=z?'没有匹配的模型，请尝试其他关键词。':'No matching models. Try another term.';document.querySelector('#lab-count').textContent=z?'未找到模型；下方保留上一次选择。':'No matches; previous selection retained below.';return}select(first)};[['全部','All'],...Array.from(new Map(models.map(m=>[m.cat[1],m.cat])).values())].forEach((cat,i)=>{let b=document.createElement('button');b.textContent=t(cat)+' · '+(i?models.filter(m=>m.cat[1]===cat[1]).length:models.length);b.dataset.cat=i?cat[1]:'';b.onclick=()=>showCat(b.dataset.cat);cats.append(b)});
let down=null;C.addEventListener('pointerdown',e=>{down=[e.clientX,e.clientY];drag=[e.clientX,e.clientY];C.setPointerCapture(e.pointerId)});C.addEventListener('pointermove',e=>{if(!drag)return;yaw+=(e.clientX-drag[0])*.012;pitch=Math.max(.08,Math.min(1.4,pitch+(e.clientY-drag[1])*.009));drag=[e.clientX,e.clientY];render()});C.addEventListener('pointerup',e=>{if(down&&Math.hypot(e.clientX-down[0],e.clientY-down[1])<5)pickAt(e);down=null});for(const ev of ['pointerup','pointercancel','lostpointercapture'])C.addEventListener(ev,()=>drag=null);
document.querySelectorAll('.lab-controls button').forEach(b=>b.onclick=()=>{switch(b.dataset.act){case'base':showBase=!showBase;b.setAttribute('aria-pressed',String(showBase));break;case'top':pitch=1.55;break;case'front':pitch=.08;yaw=0;break;case'left':yaw-=.3;break;case'right':yaw+=.3;break;case'up':pitch=Math.min(1.4,pitch+.15);break;case'down':pitch=Math.max(.08,pitch-.15);break;case'explode':exploded=!exploded;b.setAttribute('aria-pressed',String(exploded));break;case'night':night=!night;b.setAttribute('aria-pressed',String(night));break;case'zoomIn':zoom=Math.min(1.7,zoom*1.15);break;case'zoomOut':zoom=Math.max(.55,zoom/1.15);break;default:yaw=.65;pitch=.42;zoom=1}render()});document.querySelector('#lab-search').addEventListener('input',e=>{query=e.target.value.toLowerCase().trim();showCat(category)});C.addEventListener('wheel',e=>{if(!e.ctrlKey)return;e.preventDefault();zoom=Math.max(.55,Math.min(1.7,zoom*Math.exp(-e.deltaY*.004)));render()},{passive:false});C.addEventListener('keydown',e=>{const actions={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down','+':'zoomIn','-':'zoomOut',Home:'reset'};if(actions[e.key]){e.preventDefault();document.querySelector('[data-act='+actions[e.key]+']').click()}});if(typeof ResizeObserver==='function')new ResizeObserver(render).observe(C);else window.addEventListener('resize',render);const entryURL=new URL(location.href),wanted=entryURL.searchParams.get('model'),found=models.findIndex((_,i)=>modelKey(i)===wanted);
