/* Public educational design-review content, adapted to civilian industrial operations. */
function designReviewData(){
 const p=(zh,en)=>[zh,en];
 const item=(n,why,evidence)=>({n,why,evidence});
 const common=[
 item(p('资产与保护目标','Assets and protection objectives'),p('按人员、生产、财产和业务连续性确定保护目标，再由项目团队评定风险和约束。','Define objectives for people, production, property and continuity before the project team evaluates risk and constraints.'),p('资产清单、风险评估、批准的设计任务书','Asset register, risk assessment, approved design brief')),
 item(p('系统集成','System integration'),p('将实体构件、电子系统、操作人员和管理程序作为一个系统审查，明确发现、延迟、事件评估与响应的职责。','Review physical elements, electronic systems, operators and procedures as one system; assign detection, delay, assessment and response responsibilities.'),p('功能需求、接口清单、责任矩阵','Functional requirements, interface register, responsibility matrix')),
 item(p('全寿命管理','Lifecycle management'),p('选型同时考虑环境适用性、维护、备件、操作培训与更换成本；交付前验证系统整体功能。','Consider environmental suitability, maintenance, spares, training and replacement costs; verify overall functionality before handover.'),p('验收计划、测试记录、运维手册、培训记录','Acceptance plan, test records, O&M manuals, training records'))
 ];
 const areas=[
 [
 item(p('围栏与门体是完整构件','Fences and gates as assemblies'),p('区分边界标识、实体隔离与经认证的保护功能；比较网片、立柱、连接件、门体及五金的适用性。','Distinguish boundary marking, physical separation and certified protective functions; consider panels, posts, fittings, gates and hardware as assemblies.'),p('产品资料、施工质量记录、维护计划','Product data, workmanship records, maintenance plan')),
 item(p('环境与设施接口','Environmental and facility interfaces'),p('将地形、排水、腐蚀、接地、维护及消防通行要求纳入跨专业设计审查。','Include terrain, drainage, corrosion, grounding, maintenance and emergency access in interdisciplinary review.'),p('土建、机电、消防会审记录','Civil, electrical and fire-safety review records')),
 item(p('视频与事件评估','Video and event assessment'),p('明确视频用途：告警评估、授权通行辅助、现场观察和证据记录；按用途验收画质、照明、记录和可用性。','Define video purposes: alarm assessment, access support, observation and evidence; accept image quality, lighting, recording and availability against those purposes.'),p('功能测试、环境适用性和记录管理要求','Functional tests, environmental suitability and record-management requirements'))
 ],
 [
 item(p('出入口的四项设计目标','Four entrance design objectives'),p('同时审查安保、人员与交通安全、通行能力及长期运营成本。','Review security, pedestrian and traffic safety, throughput and long-term operating costs together.'),p('交通与安全研究、业务量需求、会审意见','Traffic and safety study, demand requirements, review comments')),
 item(p('车辆阻挡与普通交通管理','Vehicle barriers and routine traffic management'),p('区别普通道闸、固定阻挡设施与主动式车辆阻挡设备。依据批准的性能要求、认证、操作安全与维护能力选型。','Distinguish ordinary traffic arms, passive barriers and active vehicle barriers. Select by approved performance requirements, certification, operational safety and maintenance capability.'),p('产品测试报告、操作安全评估、维护及培训资料','Product test reports, operational safety review, maintenance and training records')),
 item(p('授权管理与人机接口','Authorization and human-machine interface'),p('明确员工、访客、承包商与物流业务的授权责任；门禁、接待、业务记录和现场操作共同支持正常通行。','Assign authorization ownership for employees, visitors, contractors and logistics; integrate access control, reception, records and operators for routine passage.'),p('授权规则、功能测试、异常业务交接记录','Authorization rules, functional tests, exception handover records'))
 ],
 [
 item(p('建筑保护与生命安全','Building protection and life safety'),p('将建筑结构、外墙、门窗、非结构构件及人员告知纳入整体设计。专业保护性能通过适用的工程评估和产品验证确定。','Consider structure, envelopes, doors, glazing, nonstructural elements and occupant notification as a whole. Specialist protective performance requires applicable engineering assessment and product verification.'),p('建筑设计文件、构件认证、消防及疏散审查','Building design documents, assembly certification, fire and egress review')),
 item(p('临建、模块化与长期住宿','Temporary, modular and enduring accommodation'),p('以使用期限、入住人数、设施条件和维护能力定义建设需求；统筹消防、用电、供水、卫生、通风和通信。','Define construction requirements by intended lifespan, occupancy, facility conditions and maintenance capability; coordinate fire safety, electrical systems, water, sanitation, ventilation and communications.'),p('入住及设施需求、检验记录、运行交接资料','Occupancy and facility requirements, inspection records, operational handover')),
 item(p('人员保护与管理责任','Personnel protection and accountability'),p('按空间用途与人员保护需求协调住宿、办公、公共服务、授权、隐私和应急信息；明确管理人及外部服务接口。','Coordinate accommodation, offices, common services, authorization, privacy and emergency communication according to space use and personnel needs; assign owners and external-service interfaces.'),p('营地管理制度、培训、应急通知及服务演练记录','Camp policies, training, notification and service exercise records'))
 ]
 ];
 const sectors=[
 [p('工艺环境与材料适用性','Process environment and material suitability'),p('危险区域电气适用性、腐蚀环境、消防及工艺安全接口由相关专业共同审查。','Relevant disciplines jointly review hazardous-area electrical suitability, corrosion, fire and process-safety interfaces.')],
 [p('地形与建设阶段','Terrain and construction phase'),p('将施工阶段、道路与重型设备作业、粉尘、维护资源及用地管理纳入设计输入。','Include construction phase, roads and heavy equipment operations, dust, maintenance resources and land management in design inputs.')],
 [p('分散资产与维护服务','Distributed assets and maintenance services'),p('以设备分布、环境适用性、供电通信和运维责任为重点审查系统持续服务能力。','Review service continuity in light of distributed equipment, environmental suitability, power, communications and maintenance ownership.')],
 [p('生产连续性与专业接口','Generation continuity and discipline interfaces'),p('将运行、检修、电气安全、消防及人员服务需求统一纳入设计评审和交付验证。','Include operations, maintenance, electrical safety, fire protection and personnel services in design review and handover verification.')]
 ];
 const evidence=p('待核查','To review'),done=p('已记录证据','Evidence recorded');
 return{common,areas,sectors,evidence,done};
}

